DO $$
DECLARE r record; used text[] := ARRAY['add_terminal_appeal_note','admin_reset_user_password','apply_salary_revision','apply_statutory_revision','approve_product_conversion','approve_registration','assign_terminal_order','assign_terminal_role','auto_assign_order_by_scope','auto_generate_penalties','cancel_scheduled_salary_revision','check_in_terminal_appeal_case','cleanup_biometric_device_pin_after_ack','cleanup_expired_records','cleanup_old_snapshots','compliance_command_centre','compliance_recompute_document_status','create_bank_transfer','create_buyer_client_with_evidence','create_inactive_assignee_notification','create_manual_purchase_complete_rpc','create_manual_purchase_complete_v2_rpc','create_manual_purchase_with_split_payments_rpc','create_role_with_permissions','create_seller_client_with_evidence','create_terminal_biometric_session','create_user_with_password','delete_all_user_webauthn_credentials','delete_purchase_order_with_reversal','delete_sales_order_with_reversal','delete_user_with_cleanup','delete_webauthn_credential','enqueue_email','ensure_onboarding_for_orphans','extend_terminal_biometric_session','fin_crypto_refresh','fin_entity_balance_sheet','fin_entity_integrity','flag_counterparty_for_payment_method_cancellations','fn_generate_payroll','fn_initialize_resignation_checklist','generate_employee_id','generate_off_market_purchase_order_number','generate_off_market_sales_order_number','generate_terminal_bypass_code','get_ad_pricing_health','get_bank_calculated_balances','get_client_usernos','get_counterparty_completed_order_count','get_counterparty_order_history','get_my_terminal_notifications','get_payment_split_mismatches','get_product_avg_costs','get_product_cost_basis','get_super_admin_ids','get_terminal_operator_workloads','get_terminal_permissions','get_terminal_user_roles','get_terminal_visible_user_ids','get_transactions_with_closing_balance','get_unpaid_tds_total','get_user_min_hierarchy_level','get_user_permissions','get_user_role_functions','get_user_with_roles','get_wallet_calculated_balances','get_webauthn_credentials','handle_sales_order_payment_method_change','has_role','has_terminal_permission','hr_apply_deposit_collection','hr_apply_loan_push','hr_apply_razorpay_advance_ack','hr_apply_statutory_change','hr_assign_shift_schedule','hr_attendance_day_detail','hr_attendance_day_range','hr_attendance_month_summary','hr_backfill_one_time_payout_from_register','hr_close_fnf_sources','hr_close_loan','hr_close_payroll_month','hr_cockpit_ack_step','hr_cockpit_month_state','hr_compoff_month_pool','hr_compute_lop_days','hr_compute_salary_structure_drift','hr_create_salary_advance','hr_delete_salary_revision','hr_derive_all_statutory_enrollments','hr_derive_statutory_enrollment_from_history','hr_doc_allocate_reference','hr_email_dispatch_health','hr_is_hr_staff','hr_mark_all_notifications_read','hr_match_employee_by_normalized_name','hr_my_payslips','hr_new_joiner_check','hr_open_unexplained_drift_count','hr_org_chart_directory','hr_payroll_cockpit_authorized','hr_payslip_import_coverage','hr_payslip_link_orphans','hr_pending_training_swaps','hr_pull_observed_salary','hr_rebuild_deposit_schedule','hr_rebuild_loan_schedule','hr_reconcile_late_early','hr_reconcile_one_time_payouts','hr_record_manual_loan_repayment','hr_resolve_stale_session','hr_roster_completeness','hr_schedule_security_deposit','hr_set_manual_day_status','hr_set_payroll_processed_on','hr_stale_session_held','hr_sync_pay_head_lines','hr_system_pulse','hr_training_ctc_adjustment','hr_unlock_attendance_period','hr_v4_recompute_range','hr_validate_regularization_proposal','hr_watchdog_open_sessions','link_client_userno','list_terminal_roles','log_biometric_event','log_terminal_small_payment_case_event','log_user_activity','mark_terminal_user_offline','match_copilot_exemplars','match_kb','next_small_sales_order_number','preview_off_market_purchase_order_number','preview_off_market_sales_order_number','process_payment_gateway_settlement','process_platform_fee_deduction','process_sales_order_wallet_deduction','process_scheduled_account_deletions','reconcile_employee_salary_structure_to_total','reconcile_purchase_order_edit','reconcile_sales_order_edit','reconcile_terminal_sync_cancellations','refresh_hour_accounts','reject_product_conversion','remove_terminal_role','request_terminal_appeal_from_small_payment','resolve_client_by_userno','resolve_inactive_assignee_notifications','reverse_bank_transaction','reverse_payment_gateway_settlement','reverse_wallet_transaction','revoke_terminal_biometric_session','run_leave_accrual','save_terminal_role','set_terminal_appeal_enabled','set_terminal_appeal_response_timer','store_webauthn_challenge','store_webauthn_credential','sync_p2p_order','sync_p2p_orders_batch','terminal_heartbeat','unassign_terminal_order','update_last_login','update_risk_flag_status','update_role_permissions','update_terminal_appeal_status','update_terminal_small_payment_case_status','update_user_profile','update_webauthn_sign_count','upsert_beneficiary_record','upsert_terminal_appeal_case','upsert_terminal_small_payment_case','user_has_permission','validate_bank_details_row','validate_terminal_biometric_session','validate_terminal_bypass_code','verify_and_consume_challenge','verify_terminal_access'];
BEGIN
  FOR r IN
    WITH refs AS (
      SELECT string_agg(coalesce(qual,'')||' '||coalesce(with_check,''),' ') t FROM pg_policies WHERE schemaname='public'
      UNION ALL SELECT string_agg(pg_get_viewdef(c.oid),' ') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m')
      UNION ALL SELECT string_agg(pg_get_constraintdef(oid),' ') FROM pg_constraint
      UNION ALL SELECT string_agg(pg_get_expr(adbin,adrelid),' ') FROM pg_attrdef
      UNION ALL SELECT string_agg(p.prosrc,' ') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND NOT p.prosecdef
    ), alltext AS (SELECT string_agg(coalesce(t,''),' ') tt FROM refs)
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace, alltext
    WHERE n.nspname='public' AND p.prosecdef
      AND p.prorettype <> 'pg_catalog.trigger'::regtype
      AND NOT (p.proname = ANY(used))
      AND alltext.tt NOT LIKE '%'||p.proname||'%'
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', r.sig);
  END LOOP;
END $$;